fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(word.len());
    
    if let Some(&first_char) = word.get(0) {
        // Capitalize the first character
        if first_char.is_lowercase() {
            result.push('A');
        } else {
            result.push(first_char);
        }
    }

    // Append the rest of the characters unchanged
    result.extend(&word[1..]);
    
    result
}